                        # Check if the 2x2 window starting at (r+dr, c+dc) contains this cell
                        pass
            # Actually simpler: count 2x2 windows that contain this cell
            # A 2x2 window at (rr, cc) covers (rr,cc), (rr,cc+1), (rr+1,cc), (rr+1,cc+1)
            for rr in range(max(0, r-1), min(r+1, 6)):
                for cc in range(max(0, c-1), min(c+1, 6)):
