                            for uc in range(cc, min(cc+2, 6)):
                                if test_in[ur][uc] != 8:
                                    window_ok = False
                                    break
                            if not window_ok:
                                break
                        if window_ok:
                            count += 1
            cell_window_counts[(r,c)] = count

